import re

def get_casing_map(domain_path, problem_path):
    with open(domain_path, 'r') as f:
        domain_text = f.read()
    with open(problem_path, 'r') as f:
        problem_text = f.read()

    # Simple regex to find names. 
    # This is not a perfect PDDL parser but should catch most objects and actions.
    names = re.findall(r'[a-zA-Z][a-zA-Z0-9\-_]*', domain_text + " " + problem_text)

    casing_map = {}
    for name in names:
        lowered = name.lower()
        if lowered not in casing_map:
            casing_map[lowered] = name
        else:
            # If we have multiple casings, we might have a problem, 
            # but usually PDDL is consistent in one file.
            # We prefer the one that has more uppercase maybe? 
            # Or just keep the first one we found.
            pass
    return casing_map

def apply_casing(name, casing_map):
    return casing_map.get(name.lower(), name)

